const graticule={source:false,target:false};
const $=id=>document.getElementById(id),source=document.createElement('canvas'),result=document.createElement('canvas');let worker,mode='out',last=null,hasResult=false;const name=n=>Atlas.jp[n]?`${Atlas.jp[n]} / ${n}`:n.replace(/([a-z])([A-Z])/g,'$1 $2');for(const id of ['src','dst'])for(const n of Atlas.catalog){let o=new Option(name(n),n);$(id).add(o)}$('src').value='Equirectangular';$('dst').value='EqualEarth';$('count').textContent=Atlas.catalog.length+' 投影法・相互変換';
function config(s){return {name:$(s==='s'?'src':'dst').value,lon:+$(s+'lon').value,lat:+$(s+'lat').value,p1:+$(s+'p1').value,p2:+$(s+'p2').value}}
function crop(){return {x:+$('cx').value,y:+$('cy').value,w:+$('cw').value,h:+$('ch').value}}
function setupSource(c,label){source.width=c.width;source.height=c.height;source.getContext('2d').drawImage(c,0,0);$('cx').value=0;$('cy').value=0;$('cw').value=c.width;$('ch').value=c.height;$('fileinfo').textContent=label+' · '+c.width+' × '+c.height;invalidate();}
function grid(ctx,c,w,h,rect){const {p,b}=Atlas.make(c);let r=rect||{x:0,y:0,w,h};ctx.save();ctx.beginPath();ctx.rect(r.x,r.y,r.w,r.h);ctx.clip();ctx.translate(r.x,r.y);ctx.scale(r.w/(b[1][0]-b[0][0]),r.h/(b[1][1]-b[0][1]));ctx.translate(-b[0][0],-b[0][1]);ctx.beginPath();d3.geoPath(p,ctx)(d3.geoGraticule10());ctx.strokeStyle='#e4c574';ctx.lineWidth=(b[1][0]-b[0][0])/w;ctx.stroke();ctx.restore();}
function render(){$('grid').checked=mode==='in'?graticule.source:graticule.target;let c=mode==='in'?source:result;if(!c.width)return;let v=$('view');v.width=c.width;v.height=c.height;const ctx=v.getContext('2d');ctx.drawImage(c,0,0);try{if(mode==='in'&&graticule.source)grid(ctx,config('s'),c.width,c.height,crop());if(mode==='out'&&graticule.target&&last)grid(ctx,last.dst,c.width,c.height)}catch{}$('maptitle').textContent=mode==='in'?'元画像':name(last?.dst.name||$('dst').value);$('dimensions').textContent=c.width+' × '+c.height+' px'+(mode==='out'?' · 透明背景':'');$('viewin').classList.toggle('active',mode==='in');$('viewout').classList.toggle('active',mode==='out');$('viewin').setAttribute('aria-pressed',String(mode==='in'));$('viewout').setAttribute('aria-pressed',String(mode==='out'));}
function invalidate(){hasResult=false;$('download').disabled=true;$('reuse').disabled=true;$('status').textContent='設定を変更しました。「この設定で変換」で更新してください。';if(mode==='in')render();}
function busy(b){$('loadsettings').disabled=b;$('settingsfile').disabled=b;$('convert').disabled=b;$('cancel').hidden=!b;$('progress').hidden=!b;for(const el of document.querySelectorAll('aside input, aside select, aside button:not(#cancel):not(#convert)'))el.disabled=b;}
function convert(){try{const c=crop();if(!source.width||![c.x,c.y,c.w,c.h].every(Number.isInteger)||c.x<0||c.y<0||c.w<1||c.h<1||c.x+c.w>source.width||c.y+c.h>source.height)throw Error('元画像内に収まる切り抜き範囲を指定してください。');for(const s of ['s','d']){if(Math.abs(config(s).lon)>180||Math.abs(config(s).lat)>90)throw Error('経度は±180°、緯度は±90°の範囲で指定してください。');Atlas.make(config(s));}worker?.terminate();worker=new Worker('worker.js');busy(true);$('progress').value=0;$('status').textContent='変換しています…';const settings={src:config('s'),dst:config('d'),crop:c,width:+$('width').value,nearest:$('sampling').value==='nearest'};worker.onmessage=({data:r})=>{if(r.error){busy(false);$('status').textContent=r.error;worker.terminate();return}if(r.done){result.width=r.w;result.height=r.h;result.getContext('2d').putImageData(new ImageData(new Uint8ClampedArray(r.pixels),r.w,r.h),0,0);last=settings;hasResult=true;mode='out';render();busy(false);$('download').disabled=false;$('reuse').disabled=false;$('status').textContent='変換完了。PNGとして保存できます。';worker.terminate();}else{$('progress').value=r.progress;$('status').textContent='変換しています… '+Math.round(r.progress*100)+'%'}};worker.onerror=()=>{busy(false);$('status').textContent='変換処理に失敗しました。解像度を下げて再試行してください。';worker.terminate()};let pixels=source.getContext('2d').getImageData(0,0,source.width,source.height).data.buffer;worker.postMessage({...settings,sw:source.width,sh:source.height,pixels},[pixels]);}catch(e){$('status').textContent=e.message}}
$('convert').onclick=convert;$('cancel').onclick=()=>{worker?.terminate();busy(false);$('status').textContent='変換を中止しました。'};for(const el of document.querySelectorAll('aside input:not(#file),aside select'))el.onchange=invalidate;$('grid').onchange=()=>{graticule[mode==='in'?'source':'target']=$('grid').checked;render()};$('viewin').onclick=()=>{mode='in';render()};$('viewout').onclick=()=>{mode='out';render()};
async function upload(f){if(!f)return;try{if(!['image/png','image/jpeg','image/webp'].includes(f.type))throw Error('PNG・JPEG・WebP画像を選んでください。');const img=await createImageBitmap(f);if(img.width*img.height>24000000){img.close();throw Error('画像が大きすぎます。2400万画素以下に縮小してください。')}setupSource(img,f.name);img.close();mode='in';render();$('status').textContent='元の投影法と中央経線を指定してから変換してください。';}catch(e){$('status').textContent=e.message}}
$('file').onchange=e=>upload(e.target.files[0]);document.body.ondragover=e=>e.preventDefault();document.body.ondrop=e=>{e.preventDefault();if(!$('convert').disabled)upload(e.dataTransfer.files[0])};
function save(blob,filename){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000)}
$('download').onclick=()=>{if(!hasResult)return;const c=document.createElement('canvas');c.width=result.width;c.height=result.height;const ctx=c.getContext('2d');ctx.drawImage(result,0,0);if(graticule.target)grid(ctx,last.dst,c.width,c.height);c.toBlob(b=>{if(b)save(b,'Atlas-'+last.dst.name+'-'+last.dst.lon+'.png');else $('status').textContent='保存に失敗しました。'},'image/png')};$('settings').onclick=()=>save(new Blob([JSON.stringify({version:1,source:config('s'),target:config('d'),crop:crop(),width:+$('width').value,sampling:$('sampling').value,graticule:{...graticule}},null,2)],{type:'application/json'}),'Atlas-settings.json');
$('reuse').onclick=()=>{if(!hasResult)return;const conf={...last.dst};setupSource(result,'変換結果');$('src').value=conf.name;for(const key of ['lon','lat','p1','p2'])$('s'+key).value=conf[key];mode='in';render();};
async function demo(){try{let topo=await(await fetch('vendor/land.json')).json();const t=topo.transform,arcs=topo.arcs.map(a=>{let x=0,y=0;return a.map(p=>{x+=p[0];y+=p[1];return [x*t.scale[0]+t.translate[0],y*t.scale[1]+t.translate[1]]})});function ring(ids){let r=[];for(const id of ids){let a=id<0?arcs[~id].slice().reverse():arcs[id];r.push(...a.slice(r.length?1:0))}return r}function geom(g){if(g.type==='GeometryCollection')return {type:g.type,geometries:g.geometries.map(geom)};return {type:g.type,coordinates:g.type==='MultiPolygon'?g.arcs.map(p=>p.map(ring)):g.arcs.map(ring)}}const land=geom(topo.objects.land);const c=document.createElement('canvas');c.width=2048;c.height=1024;const ctx=c.getContext('2d'),p=d3.geoEquirectangular().scale(2048/(2*Math.PI)).translate([1024,512]);ctx.fillStyle='#a4c1bb';ctx.fillRect(0,0,c.width,c.height);ctx.beginPath();d3.geoPath(p,ctx)(land);ctx.fillStyle='#eee9d4';ctx.fill();ctx.strokeStyle='#718f78';ctx.lineWidth=1;ctx.stroke();$('src').value='Equirectangular';$('slon').value=0;$('slat').value=0;setupSource(c,'サンプル世界地図');convert();}catch(e){$('status').textContent='サンプルを読み込めませんでした。地図画像を選択してください。'}}$('demo').onclick=demo;demo();
$('loadsettings').onclick=()=>{$('settingsfile').value='';$('settingsfile').click();};
$('settingsfile').onchange=async e=>{
  const file=e.target.files[0];if(!file)return;
  try{
    if(file.size>1024*1024)throw Error('設定ファイルが大きすぎます。保存した設定JSONを選択してください。');
    let data;try{data=JSON.parse(await file.text());}catch{throw Error('JSONを読み取れませんでした。保存した設定JSONを選択してください。');}
    if($('convert').disabled)throw Error('変換が終わってから設定を読み込んでください。');
    validateSettings(data,Atlas.catalog,source.width,source.height);
    Atlas.make(data.source);Atlas.make(data.target);
    for(const [prefix,conf] of [['s',data.source],['d',data.target]]){
      $(prefix==='s'?'src':'dst').value=conf.name;
      for(const key of ['lon','lat','p1','p2'])$(prefix+key).value=conf[key];
    }
    for(const key of ['x','y','w','h'])$('c'+key).value=data.crop[key];
    $('width').value=data.width;$('sampling').value=data.sampling;
    if(data.graticule){graticule.source=data.graticule.source;graticule.target=data.graticule.target;}
    mode='in';invalidate();render();
    $('status').textContent='設定を読み込みました。元画像を確認して「この設定で変換」を押してください。';
  }catch(error){$('status').textContent='設定読み込みエラー：'+error.message;}
  finally{e.target.value='';}
};
